#!/usr/bin/env node
/**
 * Derives src/data/stations.bundled.json from the API repo's committed seed SQL.
 *
 * The seed is the single source of truth; this only reshapes it. Run manually
 * after the seed changes, then commit the result — the app build never invokes
 * this, and the app must build with no sibling repo present.
 *
 * Usage: node scripts/build-stations-bundle.mjs [path-to-dev_stations.sql]
 */
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const seedPath =
  process.argv[2] ?? resolve(here, "../../api/seeds/dev_stations.sql");
const outPath = resolve(here, "../src/data/stations.bundled.json");
const noticePath = resolve(here, "../src/data/stations.bundled.NOTICE.md");

const sql = readFileSync(seedPath, "utf8");

const stationRe =
  /INSERT INTO stations \(id, name, region, district, lat, lng, active\) VALUES\s*\(\s*'([^']+)',\s*'((?:[^']|'')*)',\s*'((?:[^']|'')*)',\s*'((?:[^']|'')*)',\s*(-?[\d.]+),\s*(-?[\d.]+),\s*(true|false)\)/g;

const contactRe =
  /INSERT INTO station_contacts \(station_id, phone, response_rate, active\) VALUES \('([^']+)', '([^']+)', ([\d.]+), (true|false)\)/g;

const unquote = (s) => s.replace(/''/g, "'");

// Inactive stations/contacts are excluded from the bundle on purpose — they
// are decommissioned. Counted and reported so the exclusion is never silent,
// and never confused with a parse failure by the guard below.
let skippedInactive = 0;
let inactiveStationCount = 0;
let inactiveContactCount = 0;

const stations = new Map();
for (const m of sql.matchAll(stationRe)) {
  const active = m[7] === "true";
  if (!active) {
    skippedInactive++;
    inactiveStationCount++;
    continue;
  }
  stations.set(m[1], {
    id: m[1],
    name: unquote(m[2]),
    region: unquote(m[3]),
    district: unquote(m[4]),
    lat: Number(m[5]),
    lng: Number(m[6]),
    contacts: [],
  });
}

let contactCount = 0;
for (const m of sql.matchAll(contactRe)) {
  const active = m[4] === "true";
  if (!active) {
    skippedInactive++;
    inactiveContactCount++;
    continue;
  }
  const station = stations.get(m[1]);
  if (!station) throw new Error(`contact references unknown station ${m[1]}`);
  station.contacts.push({
    phone: m[2],
    responseRate: Number(m[3]),
    active: true,
  });
  contactCount++;
}

const rows = [...stations.values()].sort((a, b) => a.name.localeCompare(b.name));

// Every "INSERT INTO stations"/"INSERT INTO station_contacts" statement in
// the seed must be accounted for — either parsed into the bundle or
// deliberately excluded as inactive. If a future seed-format change breaks
// only some INSERTs, the naive "zero rows" / "zero contacts" checks below
// would not catch it: this guard would. Expectations are derived from the
// file itself, never hardcoded, so a legitimately larger seed needs no
// changes here.
const expectedStations =
  (sql.match(/INSERT INTO stations /g) ?? []).length - inactiveStationCount;
const expectedContacts =
  (sql.match(/INSERT INTO station_contacts /g) ?? []).length -
  inactiveContactCount;

if (rows.length !== expectedStations) {
  throw new Error(
    `parsed ${rows.length} stations but the seed contains ${expectedStations} INSERT statements — ` +
      `the station regex no longer matches the seed's format`
  );
}
if (contactCount !== expectedContacts) {
  throw new Error(
    `parsed ${contactCount} contacts but the seed contains ${expectedContacts} INSERT statements — ` +
      `the contact regex no longer matches the seed's format`
  );
}

if (rows.length === 0) throw new Error("parsed zero stations — seed format changed?");
for (const s of rows) {
  if (s.contacts.length === 0) throw new Error(`station ${s.name} has no contacts`);
}

mkdirSync(dirname(outPath), { recursive: true });
writeFileSync(outPath, JSON.stringify(rows, null, 2) + "\n");

const notice = `# stations.bundled.json — generated data, do not hand-edit

This file is generated by \`scripts/build-stations-bundle.mjs\` from the API
repo's committed seed (\`api/seeds/dev_stations.sql\`). Do not edit
\`stations.bundled.json\` by hand — re-run \`npm run build:stations\` instead.
This notice is regenerated on every run so it cannot drift from the data.

## Counts

- Stations: ${rows.length}
- Contacts: ${contactCount}
- Inactive rows excluded (decommissioned, not shipped): ${skippedInactive}

## Source and licensing

- Coordinates and station names originate from OpenStreetMap
  (\`amenity=fire_station\`), which is licensed **ODbL (Open Database
  License)**. Region and district come from OSM Nominatim reverse geocoding,
  also ODbL.
- The ODbL requires **attribution** and is **share-alike**: databases
  produced by extracting/reshaping ODbL data are themselves derivative
  databases and inherit the share-alike obligation. This bundle is such a
  derived database. Whether that obligation is satisfied for a shipped
  product is a licensing decision for the product owner, not something this
  generator resolves.

## Data-quality caveats (carried from the seed's own header)

- \`responseRate\` encodes **publication order** on the GNFS contact-numbers
  page, not measured or reported reliability. The field name overstates what
  the values mean.
- Contact numbers are **regional command lines, not per-station direct
  lines**, and were archived from the GNFS site on **2022-08-09**. They may
  be stale.
- **NOT VERIFIED FOR EMERGENCY USE.** Confirm every number directly with
  GNFS before any production/emergency-facing deployment.
`;
writeFileSync(noticePath, notice);

console.error(
  `wrote ${rows.length} stations / ${contactCount} contacts (${skippedInactive} inactive) -> ${outPath}`
);
